CREATE COLLATION IF NOT EXISTS public.km_natural (provider = icu, locale = 'tr-u-kn-true-ks-level1', deterministic = false);
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS image_original_url text, ADD COLUMN IF NOT EXISTS image_thumbnail_url text, ADD COLUMN IF NOT EXISTS revision bigint NOT NULL DEFAULT 0;
CREATE OR REPLACE FUNCTION public.bump_product_revision() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.revision := OLD.revision + 1; RETURN NEW; END $$;
CREATE TRIGGER product_revision BEFORE UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION public.bump_product_revision();
CREATE OR REPLACE FUNCTION public.apply_stock_adjustment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN SELECT stock INTO NEW.previous_stock FROM products WHERE id=NEW.product_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Ürün bulunamadı'; END IF; NEW.created_by:=COALESCE(NEW.created_by,auth.uid()); UPDATE products SET stock=NEW.new_stock WHERE id=NEW.product_id; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.catalog_norm(_text text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT regexp_replace(lower(coalesce(_text,'') COLLATE "tr-x-icu"),'[[:space:].-]','','g') $$;
CREATE OR REPLACE FUNCTION public.catalog_page(_q text DEFAULT '', _category text DEFAULT '', _brand text DEFAULT '', _model text DEFAULT '', _page integer DEFAULT 1, _slug text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$
DECLARE result jsonb; total_count integer; page_no integer; BEGIN
IF length(_q)>200 OR _page<1 OR _page>100000 THEN RAISE EXCEPTION 'Geçersiz filtre'; END IF;
WITH filtered AS (SELECT p.id FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE (_slug='' OR p.slug=_slug) AND (_category='' OR c.slug=_category) AND (_brand='' OR EXISTS (SELECT 1 FROM product_vehicles v JOIN brands b ON b.id=v.brand_id WHERE v.product_id=p.id AND b.slug=_brand)) AND (_model='' OR EXISTS (SELECT 1 FROM product_vehicles v JOIN brands b ON b.id=v.brand_id WHERE v.product_id=p.id AND (v.model_id::text=_model OR (v.model_id IS NULL AND b.slug=_brand)))) AND (catalog_norm(_q)='' OR catalog_norm(p.sku)=catalog_norm(_q) OR position(catalog_norm(_q) IN catalog_norm(p.name))>0 OR EXISTS (SELECT 1 FROM product_oem_numbers o WHERE o.product_id=p.id AND position(catalog_norm(_q) IN catalog_norm(o.oem))>0))) SELECT count(*) INTO total_count FROM filtered;
page_no:=least(_page,greatest(1,ceil(total_count/24.0)::int));
WITH filtered AS (SELECT p.* FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE (_slug='' OR p.slug=_slug) AND (_category='' OR c.slug=_category) AND (_brand='' OR EXISTS (SELECT 1 FROM product_vehicles v JOIN brands b ON b.id=v.brand_id WHERE v.product_id=p.id AND b.slug=_brand)) AND (_model='' OR EXISTS (SELECT 1 FROM product_vehicles v JOIN brands b ON b.id=v.brand_id WHERE v.product_id=p.id AND (v.model_id::text=_model OR (v.model_id IS NULL AND b.slug=_brand)))) AND (catalog_norm(_q)='' OR catalog_norm(p.sku)=catalog_norm(_q) OR position(catalog_norm(_q) IN catalog_norm(p.name))>0 OR EXISTS (SELECT 1 FROM product_oem_numbers o WHERE o.product_id=p.id AND position(catalog_norm(_q) IN catalog_norm(o.oem))>0)) ORDER BY nullif(btrim(p.sku),'') COLLATE public.km_natural NULLS LAST,p.id LIMIT 24 OFFSET (page_no-1)*24), rows AS (SELECT to_jsonb(p)-'revision' || jsonb_build_object('category',(SELECT jsonb_build_object('id',c.id,'name',c.name,'slug',c.slug) FROM categories c WHERE c.id=p.category_id),'oems',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'oem',o.oem)) FROM product_oem_numbers o WHERE o.product_id=p.id),'[]'::jsonb),'vehicles',coalesce((SELECT jsonb_agg(jsonb_build_object('id',v.id,'brand_id',v.brand_id,'model_id',v.model_id,'brand',jsonb_build_object('name',b.name,'slug',b.slug),'model',CASE WHEN m.id IS NULL THEN NULL ELSE jsonb_build_object('name',m.name) END)) FROM product_vehicles v JOIN brands b ON b.id=v.brand_id LEFT JOIN vehicle_models m ON m.id=v.model_id WHERE v.product_id=p.id),'[]'::jsonb)) AS item, p.sku,p.id FROM filtered p) SELECT coalesce(jsonb_agg(item ORDER BY nullif(btrim(sku),'') COLLATE public.km_natural NULLS LAST,id),'[]'::jsonb) INTO result FROM rows;
RETURN jsonb_build_object('products',result,'total',total_count,'page',page_no); END $$;
REVOKE ALL ON FUNCTION public.catalog_page(text,text,text,text,integer,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.catalog_page(text,text,text,text,integer,text) TO anon,authenticated,service_role;
CREATE TABLE public.order_requests(user_id uuid NOT NULL, request_key uuid NOT NULL, payload jsonb NOT NULL, order_id uuid NOT NULL REFERENCES public.orders(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,request_key));
GRANT SELECT ON public.order_requests TO authenticated; GRANT ALL ON public.order_requests TO service_role; ALTER TABLE public.order_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY "Own order requests" ON public.order_requests FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.place_order_once(_items jsonb,_notes text,_request_key uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE existing order_requests; canonical jsonb; oid uuid; BEGIN IF auth.uid() IS NULL OR _request_key IS NULL THEN RAISE EXCEPTION 'Giriş gerekli'; END IF; IF jsonb_typeof(_items) IS DISTINCT FROM 'array' OR jsonb_array_length(_items)>500 THEN RAISE EXCEPTION 'Geçersiz sepet'; END IF; canonical:=jsonb_build_object('items',(SELECT jsonb_agg(jsonb_build_object('product_id',pid,'quantity',qty) ORDER BY pid) FROM (SELECT (e->>'product_id')::uuid pid,sum((e->>'quantity')::integer) qty FROM jsonb_array_elements(_items)e GROUP BY 1)t),'notes',nullif(trim(_notes),'')); PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||_request_key::text,0)); SELECT * INTO existing FROM order_requests WHERE user_id=auth.uid() AND request_key=_request_key; IF FOUND THEN IF existing.payload IS DISTINCT FROM canonical THEN RAISE EXCEPTION 'İşlem anahtarı farklı siparişte kullanılamaz'; END IF; RETURN existing.order_id; END IF; oid:=place_order(_items,_notes); INSERT INTO order_requests VALUES(auth.uid(),_request_key,canonical,oid,now()); RETURN oid; END $$;
REVOKE ALL ON FUNCTION public.place_order_once(jsonb,text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.place_order_once(jsonb,text,uuid) TO authenticated,service_role;
CREATE TABLE public.import_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by uuid NOT NULL DEFAULT auth.uid(), filename text NOT NULL CHECK(length(filename) BETWEEN 1 AND 255), created_at timestamptz NOT NULL DEFAULT now(), rolled_back_at timestamptz, rolled_back_by uuid);
GRANT SELECT ON public.import_batches TO authenticated; GRANT ALL ON public.import_batches TO service_role; ALTER TABLE public.import_batches ENABLE ROW LEVEL SECURITY; CREATE POLICY "Admin read batches" ON public.import_batches FOR SELECT TO authenticated USING(has_role(auth.uid(),'admin'));
CREATE TABLE public.import_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES public.import_batches(id), product_id uuid NOT NULL REFERENCES public.products(id), previous_data jsonb NOT NULL, applied_data jsonb NOT NULL, applied_revision bigint NOT NULL, was_created boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.import_items TO authenticated; GRANT ALL ON public.import_items TO service_role; ALTER TABLE public.import_items ENABLE ROW LEVEL SECURITY; CREATE POLICY "Admin read import items" ON public.import_items FOR SELECT TO authenticated USING(has_role(auth.uid(),'admin'));
CREATE INDEX import_items_batch_idx ON public.import_items(batch_id);
CREATE POLICY "Admin upload product photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='product-photos' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin manage product photos" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='product-photos' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin list product photos" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='product-photos' AND public.has_role(auth.uid(),'admin'));